export class LightmapPagePool{
 constructor(){this.pages=new Map();}
 async acquire(path,index,map){const key=path+'|'+index;let entry=this.pages.get(key);if(!entry||entry.map.pixels!==map.pixels||entry.map.width!==map.width||entry.map.height!==map.height){entry={map,refs:0};entry.ready=decodeLightmapPixels(map).then(pixels=>{const t=new THREE.DataTexture(pixels,map.width,map.height,THREE.RGBAFormat,THREE.HalfFloatType);t.channel=1;t.flipY=false;t.generateMipmaps=false;t.minFilter=t.magFilter=THREE.LinearFilter;t.colorSpace=THREE.NoColorSpace;t.needsUpdate=true;return t;});this.pages.set(key,entry);}entry.refs++;let released=false;const dispose=()=>{if(released)return;released=true;if(--entry.refs===0){if(this.pages.get(key)===entry)this.pages.delete(key);entry.ready.then(t=>t.dispose(),()=>{});}};try{return{texture:await entry.ready,dispose};}catch(e){dispose();throw e;}}
}
export async function prepareLightmapBindings(root,objectId,asset,{pool=new LightmapPagePool(),path='lightmap'}={}){
 if(!validLightmapAsset(asset))throw Error('라이트맵 에셋 형식을 확인하세요.');const meshes=new Map(lightmapMeshes(root,objectId).map(r=>[r.key,r.mesh])),bindings=[],leases=new Map();
 try{for(const map of asset.bindings){if(!map.key.startsWith(objectId+'|'))continue;const mesh=meshes.get(map.key),source=mesh?.userData.hbLightmapOriginalGeometry||mesh?.geometry,uv=source?.getAttribute('uv1');if(!mesh||!uv||uv.itemSize!==2||mesh.isSkinnedMesh||mesh.isInstancedMesh||Object.values(source.morphAttributes||{}).some(v=>v.length))throw Error('라이트맵의 정적 메시·UV 1이 변경됐어요.');if(await lightmapGeometryRevision(mesh)!==map.geometrySHA256)throw Error('라이트맵의 기하·배치가 변경됐어요. 다시 베이크하세요.');let lease=leases.get(map.page);if(!lease){lease=await pool.acquire(path,map.page,asset.maps[map.page]);leases.set(map.page,lease);}const geometry=new THREE.BufferGeometry();for(const [name,attribute]of Object.entries(source.attributes))geometry.setAttribute(name,attribute);geometry.setIndex(source.index);geometry.groups=source.groups.map(g=>({...g}));geometry.drawRange={...source.drawRange};geometry.boundingBox=source.boundingBox?.clone()||null;geometry.boundingSphere=source.boundingSphere?.clone()||null;const coordinates=new Float32Array(uv.count*2),[sx,sy,ox,oy]=map.scaleOffset;for(let i=0;i<uv.count;i++){coordinates[i*2]=uv.getX(i)*sx+ox;coordinates[i*2+1]=uv.getY(i)*sy+oy;}geometry.setAttribute('uv1',new THREE.BufferAttribute(coordinates,2));bindings.push({mesh,texture:lease.texture,geometry,originalGeometry:source,versions:[source.index,...Object.values(source.attributes)].filter(Boolean).map(a=>({attribute:a,version:a.isInterleavedBufferAttribute?a.data.version:a.version})),world:mesh.matrixWorld.clone(),valid:true});}if(!bindings.length&&asset.bindings.length)throw Error('이 오브젝트의 라이트맵 바인딩이 없어요.');return{bindings,leases:[...leases.values()]};}catch(e){for(const b of bindings)b.geometry.dispose();for(const lease of leases.values())lease.dispose();throw e;}
}
const standard=m=>m.isMeshStandardMaterial||m.isMeshStandardNodeMaterial;
export function setLightmapReflectionMix(bindings,enabled){for(const b of bindings||[])for(const m of Array.isArray(b.mesh.material)?b.mesh.material:[b.mesh.material])if(standard(m)&&m.userData.hbProbeLightmapMixing!==(enabled===true)){m.userData.hbProbeLightmapMixing=enabled===true;m.needsUpdate=true;}}
export function setLightmapIntensity(bindings,intensity){for(const b of bindings||[])for(const m of Array.isArray(b.mesh.material)?b.mesh.material:[b.mesh.material])if(standard(m))m.lightMapIntensity=b.valid?intensity:0;}
const inPlaceProperties=['lightmapReflectionMix','lightmapIntensity','castShadow','receiveShadow','motionVectors'];
// Only the explicit runtime property setter uses this comparison; ordinary frames do no extra serialization.
export function syncMeshRendererProperties(group,object,signature){
 if(!group||group.userData.disposed||typeof group.userData.componentSignature!=='string')return false;
 const normalize=value=>{const rows=JSON.parse(value);if(!Array.isArray(rows))throw Error();return JSON.stringify(rows.map(c=>{if(c.type!=='MeshRenderer')return c;const p={...componentDefaults('MeshRenderer'),...c.properties};for(const key of inPlaceProperties)delete p[key];return{...c,properties:Object.fromEntries(Object.keys(p).sort().map(k=>[k,p[k]]))};}));};
 try{if(normalize(group.userData.componentSignature)!==normalize(signature))return false;}catch{return false;}
 const component=object.components?.find(c=>c.type==='MeshRenderer');if(!component)return false;
 const p={...componentDefaults('MeshRenderer'),...component.properties},old={...componentDefaults('MeshRenderer'),...JSON.parse(group.userData.componentSignature).find(c=>c.type==='MeshRenderer')?.properties},enabled=p.lightmapReflectionMix===true,changed=group.userData.lightmapReflectionMix!==enabled,propertyChanged=inPlaceProperties.some(key=>old[key]!==p[key]);
 group.userData.componentSignature=signature;group.userData.lightmapReflectionMix=enabled;group.userData.lightmapIntensity=p.lightmapIntensity;setLightmapReflectionMix(group.userData.lightmapBindings,enabled);
 group.traverse?.(child=>{if(child.isMesh&&!child.userData.sprite){child.castShadow=p.castShadow!==false&&child.userData.hbModelOverrides?.castShadow!==false;child.receiveShadow=p.receiveShadow!==false&&child.userData.hbModelOverrides?.receiveShadow!==false;child.userData.hbMotionVectors=p.motionVectors||'perObject';}});
 const d=group.userData.lightmapDiagnostic,amount=d&&(d.source==='realtime'||!d.valid)?0:p.lightmapIntensity;group.userData.lightmapEffective=amount;setLightmapIntensity(group.userData.lightmapBindings,amount);if(d){d.requestedIntensity=p.lightmapIntensity;d.effectiveIntensity=amount;d.reflectionMixEnabled=enabled;d.reflectionMixEligible=enabled&&d.valid&&amount>0;if(changed)d.inPlaceMixUpdates=(d.inPlaceMixUpdates||0)+1;if(propertyChanged)d.inPlacePropertyUpdates=(d.inPlacePropertyUpdates||0)+1;}
 return true;
}
export const syncLightmapReflectionMix=syncMeshRendererProperties;
export async function applyLightmapBindings(bindings,intensity=1,{own=()=>true,alive=()=>true,mixReflections=false}={}){
 const seen=new Map(),plans=[],clones=[];try{for(const b of bindings){const array=Array.isArray(b.mesh.material),materials=(array?b.mesh.material:[b.mesh.material]).map(original=>{if(!standard(original))return original;let textures=seen.get(original);if(!textures){textures=new Map();seen.set(original,textures);}if(textures.has(b.texture))return textures.get(b.texture);const material=textures.size?original.clone():original;if(material!==original)clones.push(material);textures.set(b.texture,material);return material;});plans.push({b,array,materials});}await Promise.all(clones.map(m=>m.userData.ready));if(!alive()){clones.forEach(m=>m.dispose());return false;}clones.forEach(own);for(const {b,array,materials}of plans){b.mesh.userData.hbLightmapOriginalGeometry=b.originalGeometry;b.mesh.geometry=b.geometry;b.mesh.material=array?materials:materials[0];for(const m of materials){if(!standard(m))continue;const mixing=mixReflections===true;if(m.userData.hbProbeLightmapMixing!==mixing){m.userData.hbProbeLightmapMixing=mixing;m.needsUpdate=true;}if(m.lightMap!==b.texture){m.lightMap=b.texture;m.needsUpdate=true;}m.lightMapIntensity=b.valid?intensity:0;}}return true;}catch(e){clones.forEach(m=>m.dispose());throw e;}
}
export function syncLightmapBindings(bindings){for(const b of bindings)b.valid=b.mesh.geometry===b.geometry&&b.mesh.matrixWorld.equals(b.world)&&b.versions.every(v=>(v.attribute.isInterleavedBufferAttribute?v.attribute.data.version:v.attribute.version)===v.version);return bindings.every(b=>b.valid);}
